    "body": "Even good fences feel tight sometimes. Barolo's DOCG code dictates the grape, the hill, and thirty-eight months of waiting before release, rules that bind every bottle before a cork goes in; Massolino works gracefully inside the wire. The bindings are real. So is what they protect.",
