    "body": "History buried is history kept. These vines grow on Vesuvius, the volcano that ended Pompeii in an afternoon, and Mastroberardino was chosen to replant the ancient vineyards inside the ruins themselves. The wine is called Christ's tears. Endings this absolute still bear fruit. Solemnly, annually.",
